public static int computeWithBinarySearch(int n) {
    int left = 1;
    int right = n;

    while (left < right) {
        int mid = left + (right - left) / 2;
        if (isBadVersion(mid)) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }

    return left;
}

public static int computeRecursive(int n) {
    return findFirstBadVersion(1, n);
}

public static int computeWithLinearSearch(int n) {
    for (int i = 1; i <= n; i++) {
        if (isBadVersion(i)) {
            return i;
        }
    }
    return -1;
}
